def api(page,role,script): return page.evaluate("""async ({role,script})=>{const headers={'content-type':'application/json','x-ictc-role':role,'x-ictc-actor-id':role==='admin'?'local-admin':'local-user'};return await new Function('headers',`return (async()=>{${script}})()` )()}""",{'role':role,'script':script})
def open_process(page,code):
 page.locator('[data-service="processes"]').first.click(); card=page.locator(f'#procedureHub [data-process-code="{code}"]'); expect(card).to_be_visible(); card.locator('.primary').click()
