  PHASE='seven-procedures';page.locator('[data-service="processes"]').first.click();hub=page.locator('#procedureHub');expect(hub.locator('.stable-process-card')).to_have_count(7);expect(hub.locator('[data-process-code="MC-01"] h2')).to_have_text('Standard e Controlli');assert hub.locator('[data-process-code="EV-01"]').count()==0;shot(page,'ux-v12-processes.png')
